import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import {
  NOT_RECORDED,
  headlineFiles,
  headlineOf,
  headlinePath,
  reportsIn,
} from './bench-headline.mjs';
import { cpuModel } from '../../documentation/docs/.vitepress/theme/perf-figures.mjs';
import { exampleBlock, unitCostsBlock } from './docs-capacity.mjs';

// The figures the documentation quotes, in English and Chinese, generated from
// the benchmark reports so that no page shows a number its report no longer has
// (D391 keeps one report of each kind and environment).
//
// Each report the pages quote keeps its headline figures in
// `<report>/headline.json` beside its `.md`, written from the report's own data
// by bench-headline.mjs, each figure with the build, the CPU model and the file
// it comes from. A page quotes them two ways, and docs-reference.mjs writes both
// (`--write`) and fails when either is not what the headlines give:
// - a named block, a table between `<!-- performance:begin <name> -->` and
//   `<!-- performance:end -->`, written by BLOCKS[name];
// - an inline span, one figure's number in the prose:
//   `<!-- perf:actions-snapshot/sustainable.postgres.E1:value -->2,609.8/s<!-- /perf -->`,
//   the report, the figure's id and the field, a dotted path for a nested one
//   (`sustainable.value`).
// Every page of the documentation that holds either is written, and the
// performance pages (PAGES) must hold the `snapshots` block. A report without a
// headline file is not quoted. No figure is computed across two reports, so
// none across two builds.

/** The reports the pages quote, in their order: the snapshots' tables, then the Axon comparisons' spans. */
export const HEADLINES = [
  'test/benchmarks/results/reports/actions-snapshot/headline.json',
  'test/benchmarks/results/reports/m5max-snapshot/headline.json',
  'test/benchmarks/results/reports/actions-axon/headline.json',
  'test/benchmarks/results/reports/m5max-axon/headline.json',
];

export const PAGES = {
  en: 'documentation/docs/en/operate/performance.md',
  zh: 'documentation/docs/zh/operate/performance.md',
};

/** The documentation's pages, by locale: every page there that quotes a figure is written. */
export const DOCS = {
  en: 'documentation/docs/en',
  zh: 'documentation/docs/zh',
};

/** The opening marker of the block `name`. */
export const begin = name => `<!-- performance:begin ${name} -->`;
export const BEGIN = begin('snapshots');
export const END = '<!-- performance:end -->';

const REPORTS =
  'https://github.com/Ahoo-Wang/Wow/blob/main/test/benchmarks/results/reports/';

const WORDS = {
  en: {
    generated:
      "<!-- Generated by .github/scripts/docs-performance.mjs from the reports' headline.json; regenerate with `pnpm docs:reference`. Do not edit. -->",
    none: 'No report quotes its figures here yet: the [reports](https://github.com/Ahoo-Wang/Wow/tree/main/test/benchmarks/results/reports) hold every measurement.',
    environments: {
      actions: 'GitHub Actions, one 4-core runner a suite',
      m5max: 'Apple M5 Max, 18 cores, 64 GB, one host',
    },
    title: (headline, environment, builds) =>
      `**${environment}**: [${headline.report}](${REPORTS}${headline.report}.md), ${builds.length === 1 ? 'build' : 'builds'} ${builds.map(b => `\`${b}\``).join(', ')}.`,
    head: '| Store | Nodes | Scenario | Keys | Peak | Sustainable | CPU, JDK, build |',
    remeasured:
      'Each figure is from the build, the JDK and the runner its row names. The scenarios are those of [What was measured](#what-was-measured).',
    cluster: where =>
      `Three nodes on ${where}: the nodes, the stores and the load generator divide the same cores, so these rows show what a cluster costs (forwarding between the nodes), not what it gains. Scaling across separate machines has not been measured.`,
    where: { actions: 'one runner', m5max: 'this one host' },
    models: n =>
      `These rows ran on ${n} CPU models, which each row names: two rows on different models do not compare the stores, nor the scenarios.`,
    jdk: jdk =>
      jdk === NOT_RECORDED
        ? 'JDK not recorded'
        : `JDK ${jdk}${major(jdk) === 25 ? '' : ' (not JDK 25)'}`,
    nodes: n => (n === 1 ? 'one' : String(n)),
    keys: { uniform: 'uniform', zipf: 'Zipf', hot: 'one hot account' },
    clients: n => `at ${n.toLocaleString('en-US')} clients`,
    openLoop: 'open loop',
    closedLoop: 'closed loop',
    p99: ms => `p99 ${ms} ms`,
    separator: ', ',
  },
  zh: {
    generated:
      '<!-- 由 .github/scripts/docs-performance.mjs 依据各报告的 headline.json 生成；用 `pnpm docs:reference` 重新生成。请勿手改。 -->',
    none: '尚无报告在此引用其数字：全部测量见[报告](https://github.com/Ahoo-Wang/Wow/tree/main/test/benchmarks/results/reports)。',
    environments: {
      actions: 'GitHub Actions，每个套件一台 4 核 runner',
      m5max: 'Apple M5 Max，18 核，64 GB，一台主机',
    },
    title: (headline, environment, builds) =>
      `**${environment}**：[${headline.report}](${REPORTS}${headline.report}.md)，构建 ${builds.map(b => `\`${b}\``).join('、')}。`,
    head: '| 存储 | 节点 | 场景 | 键 | 峰值 | 可持续 | CPU、JDK、构建 |',
    remeasured:
      '每个数字都来自其所在行注明的构建、JDK 与机器。各场景见[测了什么](#what-was-measured)。',
    cluster: where =>
      `三个节点在${where}上：节点、存储与负载生成器分用同一组 CPU 核，所以这几行显示的是集群的开销（节点之间的转发），不是它带来的收益。跨多台机器的扩展尚未测量。`,
    where: { actions: '同一台 runner', m5max: '同一台主机' },
    models: n =>
      `这些行来自 ${n} 种 CPU 型号，每行注明了自己的型号：型号不同的两行既不能用来比较存储，也不能用来比较场景。`,
    jdk: jdk =>
      jdk === NOT_RECORDED
        ? '未记录 JDK'
        : `JDK ${jdk}${major(jdk) === 25 ? '' : '（不是 JDK 25）'}`,
    nodes: n => (n === 1 ? '一个' : String(n)),
    keys: { uniform: '均匀', zipf: 'Zipf', hot: '单个热点账户' },
    clients: n => `${n.toLocaleString('en-US')} 个客户端`,
    openLoop: '开环',
    closedLoop: '闭环',
    p99: ms => `p99 ${ms} ms`,
    separator: '，',
  },
};

const STORES = { postgres: 'PostgreSQL', mongo: 'MongoDB' };

/** A JDK version's major version: `25.0.5+8` is 25. */
const major = jdk => Number(String(jdk).split(/[.+]/)[0]);

const rate = value =>
  `${value.toLocaleString('en-US', { maximumFractionDigits: 1 })}/s`;

/**
 * A CPU model as a table row names it: the figures' name (cpuModel), less the M5 Max's cores and memory, which the
 * environment's title gives.
 */
export const cpuName = cpu => cpuModel(cpu).replace(/, 18 cores, 64 GB$/, '');

/**
 * The rows of a headline the page's table shows, each `{ store, nodes, scenario, keys, peak?, sustainable?, cpu,
 * commit }`: a single node's sustainable rates with their closed-loop saturation (Actions, `sustainable`), or the
 * sweeps' peaks and sustainable steps (M5 Max, `sweep`; not the steps measured past a sweep, nor a fixed run).
 */
export function rowsOf(headline) {
  return headline.figures.flatMap(figure => {
    if (figure.kind === 'sustainable') {
      return [
        {
          ...figure,
          peak: figure.saturation
            ? {
                value: figure.saturation,
                loop: 'closed',
                lowerBound: figure.saturationLowerBound,
              }
            : undefined,
          sustainable: {
            value: figure.value,
            p99Ms: figure.p99Ms,
            loop: 'open',
          },
        },
      ];
    }
    if (
      figure.kind === 'sweep' &&
      !figure.single &&
      /-sweep$/.test(figure.id)
    ) {
      return [
        {
          ...figure,
          peak: Number.isFinite(figure.value)
            ? {
                value: figure.value,
                clients: figure.clients,
                lowerBound: figure.lowerBound,
              }
            : undefined,
          sustainable: figure.sustainable ?? undefined,
        },
      ];
    }
    return [];
  });
}

/** A figure's cell: its rate, `≥` for a lower bound, where it was measured, and its p99 when it has one. */
const cell = (words, figure) =>
  figure
    ? [
        `${figure.lowerBound ? '≥ ' : ''}${rate(figure.value)}`,
        figure.clients
          ? words.clients(figure.clients)
          : figure.loop === 'closed'
            ? words.closedLoop
            : words.openLoop,
        figure.p99Ms === undefined ? '' : words.p99(figure.p99Ms),
      ]
        .filter(Boolean)
        .join(words.separator)
    : '–';

/**
 * A headline as the page reads it, refusing one that lacks what the table needs: `schema`, `report`, `environment`
 * and `figures`, each figure an `id`, a `kind`, and its `commit`, `cpu`, `jdk` and `source`, and a quoted row a known
 * store.
 */
export function checkedHeadline(headline, path) {
  const missing = ['schema', 'report', 'environment', 'figures'].filter(
    key => headline[key] === undefined,
  );
  if (missing.length > 0)
    throw new Error(`${path} lacks ${missing.join(', ')}`);
  for (const [i, figure] of headline.figures.entries()) {
    const lacks = ['id', 'kind', 'commit', 'cpu', 'jdk', 'source'].filter(
      key => figure[key] === undefined,
    );
    if (lacks.length > 0)
      throw new Error(`${path}: figure ${i + 1} lacks ${lacks.join(', ')}`);
  }
  for (const row of rowsOf(headline)) {
    if (!STORES[row.store])
      throw new Error(
        `${path}: ${row.id} lacks a known store (${Object.keys(STORES).join(', ')})`,
      );
  }
  return headline;
}

/** The block between the markers, in `locale`, from the headlines: per report, its builds and its table. */
export function performanceBlock(locale, headlines) {
  const words = WORDS[locale];
  const quoted = headlines.filter(headline => rowsOf(headline).length > 0);
  if (quoted.length === 0) return [words.generated, '', words.none].join('\n');
  const table = rows => [
    words.head,
    '| --- | ---: | --- | --- | --- | --- | --- |',
    ...rows.map(row => {
      const cells = [
        STORES[row.store],
        words.nodes(row.nodes),
        row.scenario,
        words.keys[row.keys] ?? row.keys,
        cell(words, row.peak),
        cell(words, row.sustainable),
        [cpuName(row.cpu), words.jdk(row.jdk), `\`${row.commit}\``].join(
          words.separator,
        ),
      ];
      return `| ${cells.map(text => String(text).replaceAll('|', '\\|')).join(' | ')} |`;
    }),
  ];
  const sections = quoted.map(headline => {
    const rows = rowsOf(headline);
    const builds = [...new Set(rows.map(row => row.commit))].sort();
    // A cluster's rows go in a table of their own, led by what they show: its nodes share one machine's cores.
    const single = rows.filter(row => row.nodes === 1);
    const cluster = rows.filter(row => row.nodes > 1);
    // Each suite may run on a machine of its own (Actions): rows on different CPU models compare nothing.
    const models = new Set(rows.map(row => cpuName(row.cpu))).size;
    return [
      words.title(
        headline,
        words.environments[headline.environment] ?? headline.environment,
        builds,
      ),
      ...(models > 1 ? ['', words.models(models)] : []),
      ...(single.length > 0 ? ['', ...table(single)] : []),
      ...(cluster.length > 0
        ? [
            '',
            words.cluster(
              words.where[headline.environment] ?? headline.environment,
            ),
            '',
            ...table(cluster),
          ]
        : []),
    ].join('\n');
  });
  return [
    words.generated,
    '',
    words.remeasured,
    '',
    sections.join('\n\n'),
  ].join('\n');
}

/** One environment's part of the block: its report's builds and tables alone. */
const environmentBlock = environment => (locale, headlines) =>
  performanceBlock(
    locale,
    headlines.filter(headline => headline.environment === environment),
  );

/**
 * The blocks a page may hold, by name: each writes its table, in a locale, from the headlines. `snapshots` holds every
 * snapshot's; `actions` and `m5max` one environment's.
 */
export const BLOCKS = {
  snapshots: performanceBlock,
  actions: environmentBlock('actions'),
  m5max: environmentBlock('m5max'),
  'unit-costs': unitCostsBlock,
  example: exampleBlock,
};

const BLOCK = /<!-- performance:begin ([^\s]*) -->|<!-- performance:end -->/g;
const SPAN =
  /<!-- perf:([^/\s]+)\/([^:\s]+):([A-Za-z0-9.]+) -->([\s\S]*?)<!-- \/perf -->/g;

/** The fields of a figure that name where it was measured, as the prose prints each. */
const WHERE = {
  commit: commit => `\`${commit}\``,
  cpu: cpu => cpuName(cpu),
  jdk: jdk => jdk,
};

/** How many CPUs a taskset list names: `0-2` is 3, `3` is 1, `0,2-3` is 3. */
export const cpuCount = list =>
  String(list)
    .split(',')
    .map(part => part.split('-').map(Number))
    .reduce((n, [from, to = from]) => n + to - from + 1, 0);

/** A pinned process's CPUs (`cpus.server`, `cpus.load`): printed as how many. */
const isCpus = field => /^cpus\.[a-z]+$/.test(field);

/**
 * A figure's field as the prose prints it: a rate (`value`, `saturation`) as `2,609.8/s`, a time (`…Ms`) as
 * `64 ms`, any other number as itself with thousands separated; its build (`commit`) as code, its CPU as a reader
 * names it, its JDK as recorded, and a pinned process's CPUs as their count.
 */
export function spanText(field, value) {
  if (isCpus(field)) return String(cpuCount(value));
  if (/Cores$/.test(field)) return value.toFixed(2);
  // An arm's figure in a list (`readyMs.0`) is printed as its list's field.
  const last = field
    .split('.')
    .filter(key => !/^\d+$/.test(key))
    .at(-1);
  if (WHERE[field]) return WHERE[field](value);
  if (last === 'value' || last === 'saturation') return rate(value);
  if (/Ms$/.test(last))
    return `${value.toLocaleString('en-US', { maximumFractionDigits: 1 })} ms`;
  return value.toLocaleString('en-US', { maximumFractionDigits: 1 });
}

/**
 * The text of field `field` (a dotted path) of figure `id` in the headline of `report`, `≥` before a peak that is a
 * lower bound (`value` of a figure whose `lowerBound` is set), or a failure naming it.
 */
function figureText(headlines, report, id, field, path) {
  const headline = headlines.find(quoted => quoted.report === report);
  if (!headline)
    throw new Error(
      `${path}: perf:${report}/${id}:${field} names no quoted report (${headlines.map(h => h.report).join(', ') || 'none'})`,
    );
  const figure = headline.figures.find(candidate => candidate.id === id);
  if (!figure)
    throw new Error(
      `${path}: perf:${report}/${id}:${field}: ${report} has no figure ${id}`,
    );
  const value = field.split('.').reduce((holder, key) => holder?.[key], figure);
  if (
    !Number.isFinite(value) &&
    !((WHERE[field] || isCpus(field)) && typeof value === 'string')
  )
    throw new Error(
      `${path}: perf:${report}/${id}:${field}: the figure has no number there`,
    );
  return `${field === 'value' && figure.lowerBound ? '≥ ' : ''}${spanText(field, value)}`;
}

/**
 * `text` with each named block's table and each inline span's figure written in `locale` from `headlines`; fails on
 * a block of no known name, a begin without its end or an end without its begin, a block inside another, and a span
 * whose report, figure or field the headlines do not hold.
 */
export function withFigures(text, locale, headlines, path) {
  const markers = [...text.matchAll(BLOCK)];
  const blocks = [];
  for (const [i, marker] of markers.entries()) {
    const name = marker[1];
    if (name === undefined) continue;
    const close = markers[i + 1];
    if (!close || close[1] !== undefined)
      throw new Error(`${path}: ${begin(name)} must be followed by ${END}`);
    if (!BLOCKS[name])
      throw new Error(
        `${path}: no block is named ${name} (${Object.keys(BLOCKS).join(', ')})`,
      );
    blocks.push({
      name,
      from: marker.index + marker[0].length,
      to: close.index,
    });
  }
  const ends = markers.filter(marker => marker[1] === undefined).length;
  if (ends !== blocks.length)
    throw new Error(`${path}: ${END} without its ${begin('<name>')}`);
  let written = '';
  let at = 0;
  for (const block of blocks) {
    written += `${text.slice(at, block.from)}\n${BLOCKS[block.name](locale, headlines)}\n`;
    at = block.to;
  }
  written += text.slice(at);
  return written.replace(
    SPAN,
    (_, report, id, field) =>
      `<!-- perf:${report}/${id}:${field} -->${figureText(headlines, report, id, field, path)}<!-- /perf -->`,
  );
}

/** The pages under `dir` (relative to `root`) that quote a figure, by a block or a span, as paths relative to root. */
function quotingPages(root, dir) {
  let entries;
  try {
    entries = readdirSync(join(root, dir), {
      recursive: true,
      withFileTypes: true,
    });
  } catch {
    return [];
  }
  return entries
    .filter(entry => entry.isFile() && entry.name.endsWith('.md'))
    .map(entry => relative(root, join(entry.parentPath, entry.name)))
    .filter(path => {
      const text = readFileSync(join(root, path), 'utf8');
      return (
        text.includes('<!-- performance:begin') || text.includes('<!-- perf:')
      );
    })
    .sort();
}

/** The headlines of the reports present in `root`, as their data gives them, in the page's order. */
export function headlinesOf(root) {
  const present = new Set(reportsIn(root).map(headlinePath));
  return HEADLINES.filter(path => present.has(path)).map(path =>
    checkedHeadline(headlineOf(root, path.split('/').at(-2)), path),
  );
}

/**
 * The pages that quote figures as the headlines give them, by path: the performance pages (PAGES), which must hold
 * the `snapshots` block, and every other page of the documentation that holds a block or a span, each with its
 * figures written; and each report's headline.json (bench-headline.mjs): docs-reference.mjs writes and checks them
 * together.
 */
export function performancePages(root) {
  const headlines = headlinesOf(root);
  const pages = {};
  for (const [locale, dir] of Object.entries(DOCS)) {
    const paths = new Set([PAGES[locale], ...quotingPages(root, dir)]);
    for (const path of paths) {
      const text = readFileSync(join(root, path), 'utf8');
      if (path === PAGES[locale] && !text.includes(BEGIN))
        throw new Error(`${path} must hold ${BEGIN} and then ${END}`);
      pages[path] = withFigures(text, locale, headlines, path);
    }
  }
  return { ...headlineFiles(root), ...pages };
}
